-- Généré par scripts/import_lot2.py — mini-jeux du lot 2 (M01, M04, M11, M12, M07). Ne pas modifier à la main.
with src as (select * from jsonb_to_recordset($n$[{"config": {"code": "M01", "engine": "board", "mechanic": "tic_tac_toe", "parameters": {"columns": 3, "default_series_wins": 1, "rows": 3, "series_wins": [1, 2, 3], "turn_timer": null}, "rounds": 12, "score": "duel", "settings": {"series_wins": {"default": 1, "label": "Victoires pour gagner la série", "options": [1, 2, 3]}}, "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "N2-076", "rules": {"details": ["Score : 1 victoire par manche gagnée ; 0 pour une nulle.", "Adaptation Noodeu : Tirage initial serveur, alternance des revanches et série plafonnée.", "Source de mécanique : Noughts and Crosses — NRICH / University of Cambridge (https://nrich.maths.org/games/noughts-and-crosses).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Le serveur tire le premier joueur ; il joue X et l'autre O. À chaque revanche acceptée par les deux, le premier joueur alterne. Une nouvelle session indépendante effectue un nouveau tirage.", "Chacun son tour place son symbole dans une case vide numérotée 0..8, ligne par ligne. Les coups hors tour, hors plateau ou sur case occupée sont refusés sans passer le tour.", "Après chaque coup, le serveur teste les trois lignes, trois colonnes et deux diagonales. Trois symboles identiques alignés gagnent immédiatement, y compris au neuvième coup.", "Sans gagnant et avec neuf cases occupées, résultat nul. Après un résultat, toute pose est interdite. Une manche gagnée vaut 1 victoire dans la série ; nulle 0 chacun.", "Une série vise 1 victoire par défaut (options 2 ou 3) ; maximum 12 manches pour éviter une boucle de nulles, puis bilan des victoires, égalité possible. La revanche commence une nouvelle session liée à l'ancienne et ne réinitialise jamais son historique."], "objective": "Alignez trois symboles sur un plateau de neuf cases.", "privacy": "Le plateau est visible par vous deux ; le serveur vérifie chaque coup.", "step_texts": {}}}, {"config": {"code": "M04", "engine": "board", "mechanic": "dots_boxes", "parameters": {"boxes": 16, "dot_columns": 5, "dot_rows": 5, "edges": 40, "turn_timer": null}, "rounds": 1, "score": "duel", "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "N2-079", "rules": {"details": ["Score : 1 point par carré, maximum total 16.", "Adaptation Noodeu : Taille mobile 5 × 5 points.", "Source de mécanique : Put Yourself in a Box — NRICH / University of Cambridge (https://nrich.maths.org/games/put-yourself-box).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Plateau Noodeu : 5 × 5 points, soit 4 × 4 cases et 40 arêtes. Un trait relie seulement deux points voisins horizontaux ou verticaux ; jamais de diagonale.", "Le premier joueur est tiré au sort, puis alterné lors d'une revanche. Un trait déjà présent est refusé sans consommation du tour. Les arêtes ont un ID canonique h:r:c (r=0..4,c=0..3) ou v:r:c (r=0..3,c=0..4).", "Le serveur ajoute le trait puis examine les une ou deux cases adjacentes. Toute case dont les quatre côtés sont maintenant fermés et qui n'a pas de propriétaire appartient au joueur qui vient de jouer.", "Chaque case nouvellement fermée rapporte exactement 1 point. Un trait qui ferme deux cases rapporte 2 points dans la même transaction. Dès qu'au moins une case est fermée, le joueur rejoue ; sinon le tour passe.", "À la fermeture des 16 cases, comparer les points : plus grand score gagnant, 8-8 égalité. Invariant : somme des points = nombre de cases attribuées ; aucun coup possible après la fin."], "objective": "Fermez des carrés et gardez la main tant que vous en complétez.", "privacy": "Le plateau est visible par vous deux ; le serveur attribue les carrés.", "step_texts": {}}}, {"config": {"code": "M11", "engine": "board", "mechanic": "rps", "parameters": {"choice_timeout_seconds": 30, "max_total_engagements": 20, "wins_target": 2}, "rounds": 20, "score": "duel", "turn": "simultaneous", "version": "noodeu-c34-1.0.0"}, "id": "N2-083", "rules": {"details": ["Score : Premier à 2 victoires décisives ; égalités 0.", "Adaptation Noodeu : Choix sur écran plutôt que geste physique.", "Adaptation Noodeu : Attente de 30 s et série plafonnée.", "Source de mécanique : Official Rules v1.0 — IFRPS (site signalé prototype) (https://ifrps.org/rules).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Trois choix structurés et stables : rock, paper, scissors. Pierre bat ciseaux ; ciseaux bat feuille ; feuille bat pierre. Un geste identique est une égalité à 0 point et ne compte pas parmi les deux victoires à atteindre.", "Chaque joueur sélectionne en privé puis verrouille. Les deux choix sont révélés dans la même transaction. Après verrouillage aucune modification, même si l'autre semble avoir perdu la connexion.", "Victoire de manche : 1 point ; premier à 2 manches décisives gagnées remporte la partie. La référence IFRPS indique elle-même être un prototype ; elle est une référence de règle consultée, pas une homologation de Noodeu.", "Chaque manche dispose de 30 secondes à partir d'un départ synchronisé. Si un choix manque à l'échéance, la manche est annulée sans dévoiler le choix isolé et sans attribuer de victoire. Les joueurs peuvent réessayer après confirmation Prêt.", "Après 20 engagements (égalités et annulations incluses), terminer sur le score courant et afficher Série écourtée ; égalité possible. Aucun vainqueur n'est inventé. La revanche nécessite deux accords et crée une nouvelle session."], "objective": "Trois gestes, un choix secret et une révélation commune.", "privacy": "Ton geste reste secret jusqu'à la révélation commune ; un geste isolé n'est jamais montré.", "step_texts": {}}}, {"config": {"code": "M12", "engine": "board", "mechanic": "nd_pig", "parameters": {"dice": 1, "target": 100, "turn_timer": null, "win_requires_hold": true}, "rounds": 1, "score": "duel", "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "nd-de-chanceux", "rules": {"details": ["Score : Score conservé ; premier à au moins 100 après S’arrêter.", "Adaptation Noodeu : Un seul dé ; aucune règle double 1.", "Adaptation Noodeu : Victoire après conservation explicite.", "Source de mécanique : Pig dice game — NSW Department of Education (https://education.nsw.gov.au/teaching-and-learning/curriculum/mathematics/everyday-maths/primary/resources/pig-dice-game).", "Source de mécanique : Optimal Play of the Dice Game Pig — Todd W. Neller et Clifton G. M. Presser / COMAP, 2004 (https://cs.gettysburg.edu/~tneller/papers/pig.pdf).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Variante à un dé : le premier joueur est tiré au sort. Son total provisoire commence à 0 ; les deux scores conservés commencent à 0.", "Lancer demande au serveur un entier uniforme de 1 à 6. Sur 2..6, ajouter ce résultat au total provisoire et conserver le tour. Le joueur peut relancer ou S'arrêter. Sur 1, perdre seulement le total provisoire et passer la main ; les points déjà conservés restent intacts.", "S'arrêter est permis si le provisoire est supérieur à 0 : le serveur l'ajoute au score conservé, remet le provisoire à 0 et passe la main. Si le score conservé atteint ou dépasse 100, la partie finit immédiatement. Pas de dernier tour accordé à l'autre.", "L'animation de dé ne calcule jamais le résultat : elle affiche die_value donné par la transaction serveur. Un double clic ou une relance réseau du même action_id renvoie le même résultat. Une nouvelle action ne peut être soumise qu'après la confirmation du précédent lancer.", "Le seuil 100 est retenu comme objectif de partie. La source NSW donne 100 à titre d'exemple mais décrit deux dés et un double 1 qui efface les points conservés : cette règle n'est pas importée. La référence universitaire Neller/Presser décrit bien le jeu à un dé. La nécessité d'appuyer sur S'arrêter avant de gagner est une précision Noodeu.", "Pas de plafond de tours imposé ; pause ou abandon individuel disponibles. Pas d'égalité au cours normal : la conservation qui atteint 100 désigne un seul gagnant. La revanche alterne le premier joueur."], "objective": "Relancez pour cumuler, ou conservez vos points avant de tomber sur un 1.", "privacy": "Le dé est lancé par le serveur ; vous voyez tous les deux chaque lancer.", "step_texts": {}}}, {"config": {"code": "M07", "engine": "board", "mechanic": "battleship", "parameters": {"adjacency": "allowed", "columns": 10, "fleet": [5, 4, 3, 3, 2], "hit_extra_turn": false, "rows": 10, "salvo": false, "shots_per_turn": 1}, "rounds": 1, "score": "duel", "turn": "alternate", "version": "noodeu-c34-1.0.0"}, "id": "N2-078", "rules": {"details": ["Score : Navires coulés et victoire ; aucun point relationnel.", "Adaptation Noodeu : Voisinage autorisé explicité.", "Adaptation Noodeu : Premier joueur serveur ; révélation finale sur accord commun.", "Adaptation Noodeu : Art et navires originaux Noodeu.", "Source de mécanique : Battleship F4527, notice française — Hasbro (https://instructions.hasbro.com/api/download/F4527_fr-fr_battleship-jeu-de-strategie-pour-enfants-a-partir-de-7-ans-pour-2-joueurs.pdf).", "Règles rédigées par Noodeu (règles originales Noodeu, sources séparées)."], "how_to": ["Variante retenue : jeu classique à un tir par tour, grille A..J × 1..10, cinq navires de longueurs 5,4,3,3,2 et 17 cases occupées. Le mode salve de la notice Hasbro n'est pas retenu.", "Chaque navire est droit, horizontal ou vertical, dans les limites, sans chevauchement. Le voisinage latéral et diagonal est autorisé (clarification Noodeu explicite ; la notice consultée ne pose pas d'interdiction de contact).", "Placement au toucher case de départ puis orientation, avec bouton Tourner ; une liste accessible navire/ligne/colonne/orientation remplace le glisser-déposer. Placement aléatoire serveur facultatif, aperçu privé puis confirmation. Aucun repositionnement après verrouillage.", "Le premier tireur est tiré au sort lorsque les deux flottes sont verrouillées. Chaque joueur tire une fois à son tour, même après touché. Un tir déjà effectué est refusé sans perte du tour. Le serveur seul calcule manqué, touché ou coulé.", "En accord avec le classique de la notice, un touché annonce le type du navire touché ; un coulé annonce son identité et marque ses cases déjà atteintes. Les autres coordonnées ne sont jamais envoyées au tireur. Le serveur annonce la victoire quand les 17 cases adverses ont été touchées.", "Pas de match nul en jeu normal alterné : le tir qui coule la dernière case termine la partie. Aucune flotte complète révélée à l'abandon. Après victoire, dévoiler les placements restants seulement si les deux demandent Voir les flottes ; sinon conserver le secret.", "La configuration 6 × 6, navires 3/2/2 de l'ancien catalogue est une autre version. Ne pas la convertir ni modifier ses parties ; l’ID N2-078 est une correspondance de jeu avec nouvelle version proposée, pas une autorisation d’écrasement."], "objective": "Placez votre flotte en secret et retrouvez celle de votre partenaire.", "privacy": "Ta flotte reste secrète : seul le résultat de chaque tir est annoncé, même après la partie.", "step_texts": {}}}]$n$::jsonb) as x(id text, rules jsonb, config jsonb)),
changed as (
  select s.* from src s join public.games g on g.id = s.id
  where not exists (select 1 from public.game_versions v where v.game_id = s.id and v.version = g.current_version
                    and v.rules = s.rules and v.config = s.config)),
ins as (
  insert into public.game_versions (game_id, version, rules, config, published_at)
  select c.id, coalesce((select max(version) from public.game_versions where game_id = c.id), 0) + 1, c.rules, c.config, now()
  from changed c returning game_id, version)
update public.games g set current_version = ins.version from ins where g.id = ins.game_id;

update public.games set implementation = 'playable', updated_at = now()
  where id in ($n$N2-076$n$, $n$N2-079$n$, $n$N2-083$n$, $n$nd-de-chanceux$n$, $n$N2-078$n$) and implementation <> 'playable' and current_version is not null;

insert into public.catalogue_imports (content_version, report)
values ($n$c14-lot2-1.0.0$n$, jsonb_build_object('partie', 'mini-jeux lot 2', 'jouables', 5));
